<script setup>
import { reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useAuth } from '../stores/auth.js'
import { errorMessage } from '../api.js'
const form = reactive({ email: '', password: '' }), error = ref(''), busy = ref(false)
const auth = useAuth(), route = useRoute(), router = useRouter()
async function submit() { busy.value = true; error.value = ''; try { await auth.login(form); const target = route.query.redirect; router.replace(typeof target === 'string' && target.startsWith('/') && !target.startsWith('//') ? target : '/dashboard') } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
</script>
<template><div class="auth-page"><section class="auth-art"><RouterLink class="brand" to="/login"><span class="brand-mark">s•</span>smartreminder</RouterLink><div><span class="eyebrow">LESS ON YOUR MIND</span><h1>A little reminder.<br>A lot more<br><em>peace of mind.</em></h1><p>Schedule the important things, and get back to living. Your reminders keep working while you’re away.</p><div class="auth-mini-card"><span>✓</span><div><strong>You’re right on time.</strong><small>A thoughtful nudge, delivered to your inbox.</small></div></div></div><small>YOUR TIME, WELL LOOKED AFTER.</small></section><section class="auth-form-wrap"><form class="auth-form" @submit.prevent="submit"><span class="eyebrow purple">WELCOME BACK</span><h2>Your day, a little lighter.</h2><p class="muted">Sign in to your reminder workspace.</p><p v-if="route.query.registered" class="notice success" role="status">Account created. You can sign in now.</p><p v-if="error" class="notice error" role="alert">{{ error }}</p><label>Email address<input v-model.trim="form.email" type="email" autocomplete="username" required maxlength="254" placeholder="you@example.com"></label><label>Password<input v-model="form.password" type="password" autocomplete="current-password" required maxlength="72" placeholder="Your password"></label><button class="button primary full" :disabled="busy">{{ busy ? 'Signing in…' : 'Sign in →' }}</button><p class="auth-switch">New here? <RouterLink to="/register">Create an account</RouterLink></p></form></section></div></template>
